AssistantMessageToolRequest(name='create', tool_call_id='tooluse_r50jdKy0CDpqSqwW6ZspZm', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', function() {
    const form = document.getElementById('quizForm');
    const resultDiv = document.getElementById('result');

    form.addEventListener('submit', function(e) {
        e.preventDefault();
        handleQuizSubmit();
    });

    function handleQuizSubmit() {
        const answers = {
            q1: getSelectedAnswers('q1'),
            q2: getSelectedAnswers('q2'),
            q3: getSelectedAnswers('q3')
        };

        const correctAnswers = {
            q1: ['cpp', 'rust'],
            q2: ['javascript', 'typescript', 'webassembly'],
            q3: ['haskell', 'javascript', 'csharp']
        };

        let score = 0;
        let feedback = [];

        for (let question in correctAnswers) {
            const selected = answers[question];
            const correct = correctAnswers[question];

            const isCorrect = 
                selected.length === correct.length &&
                selected.every(answer => correct.includes(answer));

            if (isCorrect) {
                score++;
                feedback.push(`Question ${question.replace('q', '')}: ✓ Correct`);
            } else {
                const correctLabels = correct.map(val => getLabelForValue(question, val)).join(', ');
                feedback.push(`Question ${question.replace('q', '')}: ✗ Correct answers: ${correctLabels}`);
            }
        }

        displayResult(score, feedback);
    }

    function getSelectedAnswers(questionName) {
        const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
        return Array.from(checkboxes).map(cb => cb.value);
    }

    function getLabelForValue(questionName, value) {
        const checkbox = document.querySelector(`input[name="${questionName}"][value="${value}"]`);
        if (checkbox) {
            const label = checkbox.closest('.checkbox-label');
            return label ? label.querySelector('span').textContent : value;
        }
        return value;
    }

    function displayResult(score, feedback) {
        const percentage = Math.round((score / 3) * 100);

        let message = `<strong>Quiz Complete!</strong><br>`;
        message += `You scored ${score}/3 (${percentage}%)<br><br>`;
        message += feedback.join('<br>');

        resultDiv.innerHTML = message;

        if (score === 3) {
            resultDiv.className = 'result-message success';
        } else {
            resultDiv.className = 'result-message info';
        }

        resultDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
});
